# Fetch the frame study. URLs signed over the ENTIRE query string -- byte-for-byte.
$ErrorActionPreference = 'Stop'
$dest = 'E:\AI\style-dataset-lab\projects\ferrochrome\outputs\candidates\frame-study'
New-Item -ItemType Directory -Force -Path $dest | Out-Null

$items = @(
  @{ name = 'squat_hauler.png'
     url  = 'https://storage.googleapis.com/comfy-cloud-assets/c089fbc603988f801310567973134caaa35aefffec92c9d164e45e0760ada835.png?X-Goog-Algorithm=GOOG4-RSA-SHA256&X-Goog-Credential=comfy-cloud-prod-workload-sa%40comfy-cloud-prod.iam.gserviceaccount.com%2F20260823%2Fauto%2Fstorage%2Fgoog4_request&X-Goog-Date=20260823T011958Z&X-Goog-Expires=21599&X-Goog-&X-Goog-SignedHeaders=host&response-content-disposition=attachment%3B%20filename%3D%22ferrochrome_frame_squat_hauler_00001.png%22' }
  @{ name = 'tall_stilt.png'
