  @{ name = 'slight_domestic.png'
     url  = 'https://storage.googleapis.com/comfy-cloud-assets/930a94767fdaa3039180c37d9356dd5232fdeeeb3a7484884a353363440bf0f2.png?X-Goog-Algorithm=GOOG4-RSA-SHA256&X-Goog-Credential=comfy-cloud-prod-workload-sa%40comfy-cloud-prod.iam.gserviceaccount.com%2F20260823%2Fauto%2Fstorage%2Fgoog4_request&X-Goog-Date=20260823T011958Z&X-Goog-Expires=21599&X-Goog-&X-Goog-SignedHeaders=host&response-content-disposition=attachment%3B%20filename%3D%22ferrochrome_frame_slight_domestic_00001.png%22' }
  @{ name = 'asym_wrench.png'
     url  = 'https://storage.googleapis.com/comfy-cloud-assets/61813bfabd7207b897efb6d0839e3c82f54579f1a2ead456e0baf2bc13f988bc.png?X-Goog-Algorithm=GOOG4-RSA-SHA256&X-Goog-Credential=comfy-cloud-prod-workload-sa%40comfy-cloud-prod.iam.gserviceaccount.com%2F20260823%2Fauto%2Fstorage%2Fgoog4_request&X-Goog-Date=20260823T011958Z&X-Goog-Expires=21599&X-Goog-&X-Goog-SignedHeaders=host&response-content-disposition=attachment%3B%20filename%3D%22ferrochrome_frame_asym_wrench_00001.png%22' }
)

foreach ($i in $items) {
  $out = Join-Path $dest $i.name
  curl.exe -L --fail-with-body --retry 3 --retry-all-errors --connect-timeout 20 -s -o $out -- $i.url
  if ($LASTEXITCODE -ne 0) { throw "download failed for $($i.name) (curl exit $LASTEXITCODE)" }
  Write-Output ("{0}  {1:N0} bytes" -f $i.name, (Get-Item $out).Length)
}
